import '../../../globals'
import React from 'react'
import { connect } from 'react-redux'
import { Row, Col, Button, Form, Input, Select, Radio, Alert, Spin, message } from 'antd'
import LayoutContent from '../../../components/utility/layoutContent'
import LayoutContentWrapper from '../../../components/utility/layoutWrapper'
import QueryString from 'query-string'
import EditTemplateStyled from './editTemplate.style'
import NotificationActions from '../../redux/notifications/actions'
import moment from 'moment-timezone'
import { get, size } from 'lodash'
import { HTMLStyled as HtmlEditorStyled } from './htmlEditor.styled'
import partnerGroupActions from '../../redux/partner/actions'
import insuranceActions from '../../../redux/policy/actions'
import HTMLPreviewer from '../Notifications/configurableTemplates'
import { addFontsToEmailHtml, getTemplateMetaData, isTemplateBuilderContent } from './configurableTemplates/helpers'

const { getMasterData, updateTemplate, resetNotificationsRedux, getTemplateDetail, closeViewBodyHtml } = NotificationActions
const { getPartners } = insuranceActions
const {
  getPartnerProductTemplateDataRequest
} = partnerGroupActions

const FormItem = Form.Item
const { TextArea } = Input
const Option = Select.Option
const RadioGroup = Radio.Group
const _ = require('lodash')
class EditTemplate extends React.Component {
  state = {
    htmlContent: '',
    masterData: {},
    getTemplateDetailStatus: '',
    templateBodyType: 'plain_text',
    queryString: QueryString.parse(this.props.location.search),
    plainEditor: '',
    paramsObject: [],
    showHTMLPreviewer: false,
    showThirdPartyFields: ['whatsapp', 'mobile_app_push', 'zalo', 'whatsapp_twilio'],
    subjectField: ['email', 'mobile_app_push']
  }

  UNSAFE_componentWillReceiveProps (nextProps) {
    const {
      masterData,
      getMasterDataStatus,
      updateTemplateStatus,
      dataDetailTemplate,
      getTemplateDetailStatus
    } = nextProps.Notifications

    if (getMasterDataStatus !== '') {
      this.setState({ masterData, getMasterDataStatus })
    }
    if (updateTemplateStatus !== '') {
      this.setState({ updateTemplateStatus, submitting: false })
    }
    if (updateTemplateStatus !== '' && updateTemplateStatus === 'success') {
      this.setState({ isUpdateTemplateSuccess: true })
    }
    if (getTemplateDetailStatus !== '' && getTemplateDetailStatus !== undefined) {
      let paramData = get(dataDetailTemplate, 'third_party_template_parameter', {})
      const modifiedParamObject = []
      if (size(paramData) > 0) {
        Object.values(paramData).forEach((item, index) => {
          const obj = {}
          obj.id = index
          obj.value = item
          modifiedParamObject.push(obj)
        })
      } else {
        paramData = { id: 0, value: '' }
        modifiedParamObject.push(paramData)
      }
      this.setState({
        dataDetailTemplate,
        getTemplateDetailStatus,
        notificationType: dataDetailTemplate.notification_type,
        paramsObject: modifiedParamObject
      }, () => {
        const parser = new DOMParser()
        const htmlData = parser.parseFromString(this.state.dataDetailTemplate.body, 'text/html')
        const contentSearch = htmlData.querySelector('.template-logo')
        if (contentSearch) {
          this.setState({
            showHTMLPreviewer: true
          })
        }
      })
      this.props.resetNotificationsRedux(['getTemplateDetailStatus'])
    }
  }

  componentDidMount () {
    const { queryString } = this.state
    this.props.getTemplateDetail(queryString)
    this.props.getMasterData()
  }

  componentWillUnmount () {
    this.props.resetNotificationsRedux()
    this.props.closeViewBodyHtml()
  }

  componentDidUpdate (_, prevState) {
    if (
      prevState.dataDetailTemplate?.body !== this.state.dataDetailTemplate?.body &&
      isTemplateBuilderContent(this.state.dataDetailTemplate?.body) &&
      this.state.templateBodyType !== 'template_builder'
    ) {
      this.setState({
        templateBodyType: 'template_builder'
      })
    }
  }

  back = () => {
    const { history } = this.props
    history.push('/notifications')
  }

  async validateForm () {
    return new Promise((resolve) => {
      this.props.form.validateFields((error, values) => {
        resolve(!error)
      })
    })
  }

  handleSubmit = async e => {
    e.preventDefault()
    this.setState({ submitting: true })
    const valid = await this.validateForm()
    if (!valid) {
      return
    }
    const { form } = this.props
    const { htmlContent, queryString, paramsObject } = this.state

    let data = form.getFieldsValue()
    if (data.body === undefined && this.state.templateBodyType === 'plain_text') {
      data = { ...data, body: htmlContent }
    }
    data = { ...data, tmpl_lang_id: queryString.code, code: queryString.id }
    if (this.state.notificationType === 'sms') {
      data = {
        ...data,
        subject: '',
        id: queryString.id,
        code: queryString.code
      }
    }

    if (this.state.templateBodyType === 'template_builder') {
      data = {
        ...data,
        body: addFontsToEmailHtml(data.body || htmlContent || this.state.dataDetailTemplate?.body).replace('<p><br></p>', '<br>')
      }
    }

    if (this.state.templateBodyType === 'plain_text') {
      data = {
        ...data,
        tmpl_lang_id: queryString.code,
        code: queryString.id
      }
    }

    const params = {}
    if (size(paramsObject) > 0) {
      paramsObject.forEach((item, index) => {
        if (item.value) {
          params[index] = item.value
        }
      })
    }
    data = { ...data, third_party_template_parameter: params }
    if ('params' in data) {
      delete data.params
    }
    if (data.third_party_template_id === '' || data.third_party_template_id === undefined) {
      data = { ...data, third_party_template_id: null }
    }

    this.props.updateTemplate(data)
  }

  handleEditorChange = (e) => {
    this.setState({
      htmlContent: e.target.innerHTML,
      isHtmlEmpty: e.target.innerHTML
    })
  }

  onCloseAlert = () => {
    this.props.resetNotificationsRedux()
    this.setState({ getTemplateDetailStatus: '' })
  }

  notificationType = notificationType => {
    this.setState({ notificationType })
  }

  handleOnEditorChange = (e) => {
    this.setState({
      templateBodyType: e.target.value
    })
  }

  getLangugeCodes = () => {
    const { masterData } = this.state
    let languageOptions = ''
    if (masterData.language_codes) {
      languageOptions = masterData.language_codes.map(d => (<Option value={d.code} key={d.id}>{d.description}</Option>
      ))
    }
    return languageOptions
  }

  handleOptions = index => {
    const { paramsObject } = this.state
    const newOption = paramsObject.filter((item) => { return item.id !== index })
    if (newOption.length < 1) {
      message.error('Atleast one option required')
      return
    }
    this.setState({ paramsObject: newOption })
  }

  addOptions = () => {
    const { paramsObject } = this.state
    const index = paramsObject[paramsObject.length - 1].id + 1
    this.setState(prevState => ({
      paramsObject: [...prevState.paramsObject,
        { id: index, value: '' }
      ]
    }))
  }

  onChangeInput = (e, id) => {
    const { paramsObject } = this.state
    const object = paramsObject.find(item => item.id === id)
    object.value = e.target.value
    this.setState({ paramsObject: paramsObject })
  }

  gettingDynamicHTML = (data) => {
    this.props.form.setFieldsValue({
      body: data
    })
    this.setState({
      htmlContent: data
    })
  }

  render () {
    const { masterData, dataDetailTemplate, notificationType, subjectField, showThirdPartyFields } = this.state
    const { form, profileData } = this.props
    const { getFieldDecorator } = form
    const { paramsObject } = this.state
    const radioStyle = {
      display: 'block',
      height: '30px',
      lineHeight: '30px'
    }
    const latestUsages = dataDetailTemplate && dataDetailTemplate.latest_usages
    let mainBodyTitle = 'HTML'
    if (dataDetailTemplate !== undefined && dataDetailTemplate.notification_type === 'sms') {
      mainBodyTitle = 'SMS'
    }
    if (this.state.notificationType === 'sms') {
      mainBodyTitle = 'SMS'
    }

    const isTemplateBuilder = isTemplateBuilderContent(this.state?.dataDetailTemplate?.body)
    const templateBuilderMetadata = getTemplateMetaData(this.state?.dataDetailTemplate?.body)
    const currentTypeIndex = +templateBuilderMetadata['template-name']?.split('Type')?.at(1)
    return (
      <div>
        <LayoutContentWrapper>
          {
            (this.state.getTemplateDetailStatus !== '' && this.state.getTemplateDetailStatus !== 'success') && (
              <Row style={{ width: '100%', marginBottom: '10px' }}>
                <Col>
                  <Alert
                    message={this.state.getTemplateDetailStatus}
                    type='error'
                    closable
                    onClose={() => this.onCloseAlert()}
                  />
                </Col>
              </Row>
            )
          }
          {
            (this.state.updateTemplateStatus !== '' && this.state.updateTemplateStatus === 'success') && (
              <Row style={{ width: '100%', marginBottom: '10px' }}>
                <Col>
                  <Alert
                    message={this.state.updateTemplateStatus}
                    type='success'
                    closable
                  />
                </Col>
              </Row>
            )
          }
          {
            (this.state.updateTemplateStatus !== '' && this.state.updateTemplateStatus !== undefined && this.state.updateTemplateStatus !== 'success') && (
              <Row style={{ width: '100%', marginBottom: '10px' }}>
                <Col>
                  <Alert
                    message={this.state.updateTemplateStatus}
                    type='error'
                    closable
                  />
                </Col>
              </Row>
            )
          }
          <LayoutContent>
            <EditTemplateStyled>
              <Row>
                <Col>
                  <Button onClick={() => this.back()}>Back</Button>
                </Col>
                <Spin spinning={dataDetailTemplate === undefined}>
                  <Form
                    onSubmit={this.handleSubmit}
                    layout={this.state.formLayout}
                    style={{ marginTop: '20px' }}
                    id='editTemplate'
                  >
                    <Row gutter={24}>
                      <Col span={24}>
                        <FormItem
                          label='Language'
                        >
                          {getFieldDecorator('language_code', {
                            rules: [
                              { required: true, message: 'language_code can not be empty' }
                            ],
                            initialValue: dataDetailTemplate !== undefined ? dataDetailTemplate.language_code : ''
                          })(
                            <Select
                              disabled
                              showSearch
                              placeholder='Select ...'
                              style={{ width: '100%' }}
                              filterOption={(input, option) => option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0}
                            >
                              {this.getLangugeCodes()}
                            </Select>
                          )}
                        </FormItem>
                        <FormItem
                          label='Description'
                        >
                          {getFieldDecorator('description', {
                            initialValue: dataDetailTemplate !== undefined ? dataDetailTemplate.description : '',
                            rules: [
                              { required: true, message: 'Description can not be empty' }
                            ]
                          })(
                            <Input size='default' className='input-box' disabled />
                          )}
                        </FormItem>
                        <FormItem
                          label='Type'
                        >
                          {getFieldDecorator('notification_type', {
                            initialValue: dataDetailTemplate !== undefined ? dataDetailTemplate.notification_type : '',
                            rules: [
                              { required: true, message: 'Notification type can not be empty' }
                            ]
                          })(
                            <Select
                              disabled
                              showSearch
                              placeholder='Select ...'
                              style={{ width: '100%' }}
                              filterOption={(input, option) => option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0}
                              onChange={() => this.notificationType()}
                            >
                              {
                                masterData.notification_types !== undefined
                                  ? masterData.notification_types.map((value, index) => (<Option key={index} value={value}>{value}</Option>))
                                  : <Option key={1} value='loading ...' disabled>Loading ...</Option>
                              }
                            </Select>
                          )}
                        </FormItem>
                        {
                          _.includes(subjectField, notificationType) &&
                            <FormItem
                              label='Subject'
                              style={{ marginBottom: '20px' }}
                            >
                              {getFieldDecorator('subject', {
                                initialValue: dataDetailTemplate !== undefined ? dataDetailTemplate.subject : '',
                                rules: [
                                  { required: true, message: 'Subject can not be empty' }
                                ]
                              })(
                                <Input size='default' className='input-box' />
                              )}
                            </FormItem>
                        }
                        {
                          _.includes(showThirdPartyFields, notificationType) &&
                            <div>
                              <FormItem
                                label='Third Party Template Id'
                                extra='eg: 1234 or HXxxxxxxxxxxxxxxxxxxxxxxxxxxxx'
                              >
                                {getFieldDecorator('third_party_template_id', {
                                  initialValue: dataDetailTemplate !== undefined ? dataDetailTemplate.third_party_template_id : '',
                                  rules: [
                                    { required: false }
                                  ]
                                })(
                                  <Input size='default' className='input-box' />
                                )}
                              </FormItem>
                              <FormItem label='Third Party Template Type'>
                                {getFieldDecorator('third_party_template_type', {
                                  initialValue: dataDetailTemplate !== undefined ? dataDetailTemplate.third_party_template_type : '',
                                  rules: [
                                    { required: false }
                                  ]
                                })(
                                  <Select
                                    showSearch
                                    placeholder='Select ...'
                                    style={{ width: '100%' }}
                                    filterOption={(input, option) => option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0}
                                  >
                                    {
                                    masterData.notification_types !== undefined
                                      ? masterData.notification_types.map((value, index) => (<Option key={index} value={value}>{value}</Option>))
                                      : <Option key={1} value='loading ...' disabled>Loading ...</Option>
                                  }
                                  </Select>
                                )}
                              </FormItem>
                              <FormItem label='Third Party Template Status'>
                                {getFieldDecorator('third_party_template_status', {
                                  initialValue: dataDetailTemplate ? dataDetailTemplate.third_party_template_status : '',
                                  rules: [
                                    { required: false }
                                  ]
                                })(
                                  <Select
                                    showSearch
                                    placeholder='Select ...'
                                    style={{ width: '100%' }}
                                  >
                                    <Option key={0} value={0}>False</Option>
                                    <Option key={1} value={1}>True</Option>

                                  </Select>
                                )}
                              </FormItem>
                            </div>
                        }
                        {
                          _.includes(['whatsapp', 'mobile_app_push', 'zalo', 'whatsapp_twilio'], notificationType) &&
                            <div>
                              {(dataDetailTemplate !== undefined) && (
                                <div className='params-field'>
                                  {
                                  paramsObject.map((d, index) => {
                                    return (
                                      <div key={index}>
                                        <span>Param -{index} </span>
                                        <Row type='flex' align='middle'>
                                          <Col sm={22}>
                                            <Input value={d.value} size='default' className='input-box' onChange={(e) => this.onChangeInput(e, d.id)} />
                                          </Col>
                                          <Col>
                                            <Button icon='delete' style={{ margin: '3px' }} onClick={() => this.handleOptions(d.id)} />
                                          </Col>
                                        </Row>
                                      </div>
                                    )
                                  })
                                }
                                  <Button icon='plus' style={{ margin: '3px' }} onClick={() => this.addOptions()} />
                                </div>
                              )}
                            </div>
                        }
                      </Col>
                      <RadioGroup onChange={this.handleOnEditorChange} value={this.state.templateBodyType} style={{ padding: '15px' }}>
                        <Radio style={radioStyle} disabled={isTemplateBuilder} value='plain_text'>PLAIN HTML</Radio>
                        {(form.getFieldsValue()?.notificationType === 'email' || isTemplateBuilder) && (<Radio style={radioStyle} disabled={!isTemplateBuilder} value='template_builder'>TEMPLATE BUILDER</Radio>)}
                      </RadioGroup>
                      {this.state.templateBodyType === 'plain_text' && (
                        <Col>
                          <div style={{ display: 'flex', alignItems: 'start', gap: '20px' }}>
                            <div style={{ width: '50%' }}>
                              <HtmlEditorStyled isEmpty={this.state.isHtmlEmpty} isSubmit={this.state.submit}>
                                <label className='custom-label' style={{ marginBottom: '10px' }}>Body {mainBodyTitle}</label>
                                <FormItem>
                                  {getFieldDecorator('body', {
                                    initialValue: dataDetailTemplate !== undefined ? dataDetailTemplate.body : this.state.htmlContent,
                                    rules: [
                                      { required: false }
                                    ]
                                  })(<TextArea autosize={{ minRows: 10, maxRows: 20 }} style={{ marginTop: '20px' }} />)}
                                </FormItem>
                              </HtmlEditorStyled>
                            </div>
                            <div style={{ width: '50%' }}>
                              <label className='custom-label'>Preview HTML</label>
                              <div className='ql-editor' style={{ marginTop: '20px' }} dangerouslySetInnerHTML={{ __html: form.getFieldsValue()?.body }} />
                            </div>
                          </div>
                        </Col>)}
                      {(isTemplateBuilder || this.state.templateBodyType === 'template_builder') &&
                        <HTMLPreviewer content={this.state?.dataDetailTemplate?.body} htmlContentFunction={this.gettingDynamicHTML} selectedTemplateIndex={currentTypeIndex - 1} />}
                      {
                        this.state.notificationType !== 'sms' && (
                          <Col>
                            <label className='custom-label'>Body (Text)</label>
                            <FormItem>
                              {getFieldDecorator('body_text', {
                                initialValue: dataDetailTemplate !== undefined ? dataDetailTemplate.body_text : '',
                                rules: [
                                  { required: false }
                                ]
                              })(
                                <TextArea
                                  autosize={{ minRows: 10, maxRows: 20 }}
                                />
                              )}
                            </FormItem>
                          </Col>
                        )
                      }
                      {
                        (latestUsages && latestUsages.length)
                          ? (
                            <Col style={{ marginTop: 10 }}>
                              <label className='custom-label'>Latest Usage</label>
                              <div style={{ border: '1px solid black', width: '100%', height: 'auto', padding: 10, margin: '5px 0px' }}>
                                {
                                  latestUsages &&
                                  latestUsages.map((item, index) => {
                                    return (
                                      <div key={index} style={{ border: '1px solid black', width: '100%', height: 'auto', padding: 10, margin: '5px 0px' }}>
                                        <Row>
                                          <Col span={4}>
                                            <b><p>Partner Code</p></b>
                                          </Col>
                                          <Col span={20}>
                                            {item && item.partner_code}
                                          </Col>
                                        </Row>
                                        <Row>
                                          <Col span={4}>
                                            <b><p>Product Key</p></b>
                                          </Col>
                                          <Col span={20}>
                                            {item && item.product_key}
                                          </Col>
                                        </Row>
                                        <Row>
                                          <Col span={4}>
                                            <b><p>TimeStamp</p></b>
                                          </Col>
                                          <Col span={20}>
                                            {item && moment.utc(item.timestamp).tz(profileData && profileData.user_timezone).format('lll')}
                                          </Col>
                                        </Row>
                                        <Row>
                                          <Col>

                                            <Row>
                                              <Col span={4}>
                                                <b><p> Trigger ID:</p></b>
                                              </Col>
                                              <Col span={20}>
                                                {item.trigger && item.trigger.id}
                                              </Col>
                                            </Row>
                                            <Row>
                                              <Col span={4}>
                                                <b><p> Trigger Name:</p></b>
                                              </Col>
                                              <Col span={20}>
                                                {item.trigger && item.trigger.name}
                                              </Col>
                                            </Row>

                                            <Row>
                                              <Col span={4}>
                                                <b><p>Trigger Type:</p></b>
                                              </Col>
                                              <Col span={20}>
                                                {item.trigger && item.trigger.trigger_type}
                                              </Col>
                                            </Row>

                                          </Col>
                                        </Row>
                                      </div>
                                    )
                                  })
                                }
                              </div>
                            </Col>
                            )
                          : ''
                      }
                    </Row>
                  </Form>
                  <Col span={24}>
                    <div style={{ textAlign: 'right', marginTop: '20px' }}>
                      <Button
                        disabled={this.state.isUpdateTemplateSuccess}
                        key='submit'
                        type='primary'
                        form='editTemplate'
                        htmlType='submit'
                        loading={this.state.submitting}
                        style={{ marginLeft: '10px' }}
                      >
                        Submit
                      </Button>
                    </div>
                  </Col>
                </Spin>
              </Row>
            </EditTemplateStyled>
          </LayoutContent>
        </LayoutContentWrapper>
      </div>
    )
  }
}

const WrappedForm = Form.create({})(EditTemplate)

export default connect(
  state => ({
    profileData: state.Auth.profile,
    Notifications: state.Notifications,
    partners: state.Insurance.partners,
    getPartnerProductTemplate: state.Partner.getPartnerProductTemplateData
  }),
  {
    getMasterData,
    updateTemplate,
    resetNotificationsRedux,
    getTemplateDetail,
    closeViewBodyHtml,
    getPartners,
    getPartnerProductTemplateDataRequest
  }
)(WrappedForm)
